import gzip, http.server, subprocess, sys, threading
body = {'/sgjp.tab.gz': (gzip.compress(b'planted gz row 5e6f\n'), 'application/gzip', None),
        '/index.json': (gzip.compress(b'{"v": "planted json 7a8b"}'), 'application/json', 'gzip')}
class H(http.server.BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass
    def do_GET(self):
        b, t, enc = body.get(self.path, (b'', 'text/plain', None))
        self.send_response(200 if b else 404); self.send_header('Content-Type', t)
        if enc:
            self.send_header('Content-Encoding', enc)
        self.end_headers(); self.wfile.write(b)
srv = http.server.ThreadingHTTPServer(('127.0.0.1', 0), H)
threading.Thread(target=srv.serve_forever, daemon=True).start()
base, bad = 'http://127.0.0.1:%d' % srv.server_address[1], []
for path, want in (('/sgjp.tab.gz', 'planted gz row 5e6f'), ('/index.json', 'planted json 7a8b')):
    p = subprocess.run([sys.executable, '_tools/fetch.py', 'text', base + path], capture_output=True, text=True, timeout=60)
    if p.returncode or want not in p.stdout:
        bad.append('%s: exit %d %r' % (path, p.returncode, (p.stdout + p.stderr)[-160:]))
srv.shutdown()
print(len(bad), 'planted gzip bodies fetch.py text did not read:', bad)
sys.exit(1 if bad else 0)

